#!/bin/sh
fm_config_path(){ case $1 in nnn) echo "$CURRENT_HOME/.config/nnn";; lf) echo "$CURRENT_HOME/.config/lf/lfrc";; ranger) echo "$CURRENT_HOME/.config/ranger/rc.conf";; yazi) echo "$CURRENT_HOME/.config/yazi/yazi.toml";; mc) echo "$CURRENT_HOME/.config/mc/ini";; tere) echo "$CURRENT_HOME/.config/tere/config.toml";; esac; }
fm_install(){ case $1 in nnn|lf|ranger|mc) pkg_install "$1";; yazi|tere) pkg_install "$1";; esac; }
fm_wizard(){ f=$1; path=$(fm_config_path "$f"); case $f in nnn) body='export NNN_OPTS="HaAde"\nexport NNN_PLUG="f:finder;o:fzopen;p:preview-tui"\nexport NNN_COLORS="1234"'; replace_block "$CURRENT_HOME/.profile" nnn "$body";; lf) mkdir -p "$(dirname "$path")"; replace_block "$path" options 'set hidden true\nset drawbox true\nset icons true\nset ignorecase true\nset preview true';; ranger) mkdir -p "$(dirname "$path")"; replace_block "$path" options 'set show_hidden true\nset preview_files true\nset draw_borders both\nset vcs_aware true';; yazi) mkdir -p "$(dirname "$path")"; write_file "$path" 644 '[manager]\nshow_hidden = true\nsort_by = "natural"\nsort_dir_first = true\nlinemode = "size"';; mc) mkdir -p "$(dirname "$path")"; write_file "$path" 644 '[Midnight-Commander]\nshow_hidden=true\nconfirm_delete=true\nuse_internal_edit=false';; tere) mkdir -p "$(dirname "$path")"; write_file "$path" 644 'mouse = true\nsearch_mode = "explicit"';; esac; ui_msg "$f" 'Recommended configuration applied.'; }
file_manager_one(){ f=$1; path=$(fm_config_path "$f"); while :; do c=$(ui_menu "$f manager" "Status: $(status_word "$f")\nConfig: $path" install 'Install package' wizard 'Apply recommended options' edit 'Edit configuration' view 'View configuration' launch 'Launch now' back Back) || { _menu_rc=$?; [ "$_menu_rc" -eq "${UI_MENU_BACK_RC:-90}" ] && return 0; return "$_menu_rc"; }; case $c in install) fm_install "$f";; wizard) case $f in nnn) nnn_full_wizard;; lf) lf_full_wizard;; ranger) ranger_full_wizard;; yazi) yazi_full_wizard;; mc) mc_full_wizard;; tere) tere_full_wizard;; esac;; edit) edit_file "$path";; view) ui_text "$f" "$(cat "$path" 2>/dev/null || echo Missing)";; launch) have "$f" && "$f" || ui_msg Missing "$f is not installed.";; back) return;; esac; done; }
file_managers_menu(){ while :; do c=$(ui_menu 'File managers' 'Install and configure terminal file managers.' wizards 'Selectable configuration wizards' nnn "nnn ($(status_word nnn))" lf "lf ($(status_word lf))" ranger "ranger ($(status_word ranger))" yazi "yazi ($(status_word yazi))" mc "Midnight Commander ($(status_word mc))" tere "tere ($(status_word tere))" back Back) || { _menu_rc=$?; [ "$_menu_rc" -eq "${UI_MENU_BACK_RC:-90}" ] && return 0; return "$_menu_rc"; }; case $c in wizards) file_manager_wizards_menu;; back) return;; *) file_manager_one "$c";; esac; done; }
